// The watch-only relay script generated by orch_dispatch, and the shell quoting
// it writes its own variables with. Moved out of the extension so the generated
// script can be rendered and tested without loading the pi runtime.

/** Quote one value for the `KEY='value'` lines a generated relay starts with. */
export function shellQuote(value) {
  return `'${String(value).replace(/'/g, `'\\''`)}'`;
}

// Written separately so the template literal below never has to escape a shell `$`.
const POLL = 'sleep "${RELAY_POLL_SECONDS:-20}"';
// Idle-without-delivery grace: 180 s of continuous idle/done is generous for a
// settling worker yet far shorter than the hours a zombie lane used to sit. Overridable.
const IDLE_GRACE = '"${IDLE_GRACE_SECONDS:-180}"';

/**
 * Pre-submit single-sourcing check for orch_dispatch (study DELIVERY-STUDY-T160,
 * proposal P1). The brief about to be submitted must literally name the report
 * path and the settle marker the relay will gate on: 11 lanes had the dispatched
 * gate path diverge from the path the brief told the worker to write. Literal
 * substring matching only -- no glob, no whitelist. Lives here with the relay
 * renderer so the check can be tested without loading the pi runtime.
 *
 * Returns the list of failed checks: "reportPath" when NEITHER the as-given path
 * nor the normalised path appears in the brief text, "marker" when the marker
 * string does not appear. An empty list means pass.
 */
export function briefMismatch(brief, reportPathGiven, reportPathNormalised, marker) {
  const failures = [];
  if (!brief.includes(reportPathGiven) && !brief.includes(reportPathNormalised)) failures.push("reportPath");
  if (!brief.includes(marker)) failures.push("marker");
  return failures;
}

/**
 * A watch-only relay. It reports a RELAY_EVENT when the agent has settled AND the
 * report carries the marker AND the report is newer than the arm-time stamp. The
 * freshness gate matters because a pre-existing stop report can already contain the
 * ready trailer, which used to settle the relay instantly as a false positive.
 *
 * Beyond settling it reports three agent facts, and nothing else:
 *   gone           -- the agent has left the herdr registry (3 confirmed reads in a row)
 *   provider_error -- the agent is blocked, which the in-agent provider-error hook
 *                     makes visible through herdr
 *   idle_no_delivery -- the agent has been CONTINUOUSLY idle/done for
 *                     IDLE_GRACE_SECONDS (default 180) without the settle gate
 *                     tripping. One event per gap, never repeated unless a working
 *                     turn comes in between (mirrors blocked_fired); it names what
 *                     is missing (report-missing vs marker-missing) and lists
 *                     task-matching files newer than the arm stamp. Plain idle
 *                     inside the grace period is idle by choice and is never alarmed.
 * The relay never stops, extends or judges anything it watches, and it reads no run
 * folder.
 *
 * Each event is written to the relay inbox first, so it survives even if the
 * Orchestrator is not listening yet. Only when that write fails does the relay fall
 * back to the older text prompt. Exactly one of the two paths runs per event, so an
 * event is never delivered twice; the settle branch never exits before one of them
 * has been attempted.
 */
export function relayScript(o) {
  return `#!/usr/bin/env bash
# Generated by orch_dispatch. Watch-only: it never edits the board, never judges the
# outcome, and never re-submits the brief. Never edit a running relay in place --
# bash reads scripts incrementally; write a fresh copy instead.
set -u
AGENT=${shellQuote(o.agent)}
TASK=${shellQuote(o.task)}
REPORT=${shellQuote(o.report)}
MARKER=${shellQuote(o.marker)}
TSK_ID=${shellQuote(o.tskId)}
RELAY_LOG=${shellQuote(o.log)}
source ${shellQuote(o.relayLib)}
STAMP=${shellQuote(o.stamp)}
relay_log "armed (watch-only) stamp=$STAMP"
prev=""
gone_reads=0
blocked_fired=no
idle_fired=no
idle_since=""
while true; do
  st=$(relay_state "$AGENT"); dm=no; fresh=no
  if [ -f "$REPORT" ] && grep -qF "$MARKER" "$REPORT" 2>/dev/null; then
    dm=yes
    [ "$REPORT" -nt "$STAMP" ] && fresh=yes
  fi
  if [ "$dm" = yes ] && [ "$fresh" = yes ] && [ "$st" != "working" ]; then
    if relay_emit_event "$TASK" "$AGENT" settled done "$REPORT"; then
      relay_log "settled event written to the relay inbox"
    else
      relay_settle "$TASK" "$AGENT" "$REPORT"
    fi
    exit 0
  fi
  if [ "$st" = gone ]; then
    # A failed read is unknown, not gone: only a registry answer of agent_not_found counts.
    if relay_is_gone "$AGENT"; then
      gone_reads=$((gone_reads + 1))
    else
      gone_reads=0
    fi
    relay_log "state=gone confirmed_reads=$gone_reads"
    if [ "$gone_reads" -ge 3 ]; then
      if relay_emit_event "$TASK" "$AGENT" gone unknown "$REPORT" "GONE_READS=$gone_reads"; then
        relay_log "gone event written to the relay inbox"
      else
        relay_fire_status "$TASK" "$AGENT" gone unknown "$REPORT" "GONE_READS=$gone_reads"
      fi
      exit 0
    fi
  else
    gone_reads=0
    if [ "$st" = blocked ]; then
      idle_since=""
      if [ "$blocked_fired" = no ]; then
        if relay_emit_event "$TASK" "$AGENT" provider_error blocked "$REPORT" "LABEL=$(relay_blocked_label "$AGENT")"; then
          relay_log "provider_error event written to the relay inbox"
        else
          relay_fire_status "$TASK" "$AGENT" provider_error blocked "$REPORT" "LABEL=$(relay_blocked_label "$AGENT")"
        fi
        blocked_fired=yes
      fi
    elif [ "$st" = working ]; then
      blocked_fired=no
      idle_fired=no
      idle_since=""
    elif [ "$st" = idle ] || [ "$st" = done ]; then
      # Idle-without-delivery: one inspect-agent event per idle/done gap, once the
      # gap has held continuously past the grace period. Only a working turn rearms it.
      if [ -z "$idle_since" ]; then idle_since=$(date +%s); fi
      if [ "$idle_fired" = no ] && [ $(( $(date +%s) - idle_since )) -ge ${IDLE_GRACE} ]; then
        if [ -f "$REPORT" ] && [ "$REPORT" -nt "$STAMP" ]; then missing=marker-missing; else missing=report-missing; fi
        matches=$(find "$(dirname "$REPORT")" -maxdepth 1 -name "$TASK*" -newer "$STAMP" 2>/dev/null | tr '\\n' ' ')
        if relay_emit_event "$TASK" "$AGENT" idle_no_delivery "$st" "$REPORT" "MISSING=$missing MATCHES=$matches"; then
          relay_log "idle_no_delivery event written to the relay inbox"
        else
          relay_fire_status "$TASK" "$AGENT" idle_no_delivery "$st" "$REPORT" "MISSING=$missing MATCHES=$matches"
        fi
        idle_fired=yes
      fi
    else
      idle_since=""
    fi
  fi
  if [ "$st" != "$prev" ]; then
    relay_log "state=$st marker=$dm fresh=$fresh"
    prev="$st"
  fi
  ${POLL}
done
`;
}
